def merge_dicts(*dicts: dict[Any, Any]) -> dict[Any, Any]:
    result = {}
    for d in dicts:
        result.update(d)
    return result


def flatten(nested: list[Any]) -> list[Any]:
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
